/// The definition of one cell of one section, by names, or `None`.
pub fn cell(section: &str, cell: &str) -> Option<&'static CellDef> {
    CELLS
        .iter()
        .find(|c| c.section == section && c.name == cell)
}

/// The definition of one section, or `None`.
pub fn section(name: &str) -> Option<&'static SectionDef> {
    SECTIONS.iter().find(|s| s.name == name)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every cell of [`CELLS`] resolves through [`cell`].
    #[test]
    fn every_cell_resolves() {
        for c in CELLS {
            let found = cell(c.section, c.name).map(|d| d.cell_index);
            assert_eq!(found, Some(c.cell_index), "{}!{}", c.section, c.name);
        }
    }

    /// Every section of [`SECTIONS`] resolves through [`section`].
    #[test]
    fn every_section_resolves() {
        for s in SECTIONS {
            let found = section(s.name).map(|d| d.section_index);
            assert_eq!(found, Some(s.section_index), "{}", s.name);
        }
    }

    /// Unknown names resolve to `None`, never to a wrong entry.
    #[test]
    fn unknown_names_are_none() {
        assert!(cell("", "").is_none());
        assert!(cell("NoSuchSection", "NoSuchCell").is_none());
        assert!(section("NoSuchSection").is_none());
    }
}
